const FaqSection = () => {
  const [activeTab, setActiveTab] = useState('platform');
  const [openIndex, setOpenIndex] = useState(null);

  const currentTab = FAQ_TABS.find(t => t.id === activeTab);

  const toggle = (i) => setOpenIndex(openIndex === i ? null : i);

  return (
    <section className="faq-section">
      {/* Hero Banner */}
      <div className="faq-hero">
        <div className="faq-hero-overlay" />
        <div className="faq-hero-content">
          <h2>How can we help you?</h2>
          <p>Find answers to frequently asked questions about our platform, data, and courses.</p>
        </div>
      </div>

      {/* Tab Bar */}
      <div className="faq-tabs-bar">
        {FAQ_TABS.map(tab => (
          <button
            key={tab.id}
            className={`faq-tab-btn ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => { setActiveTab(tab.id); setOpenIndex(null); }}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Accordion */}
      <div className="faq-body container">
        <div className="faq-accordion">
          {currentTab.questions.map((item, i) => (
            <div key={i} className={`faq-item ${openIndex === i ? 'open' : ''}`}>
              <button className="faq-question" onClick={() => toggle(i)}>
                <span>{item.q}</span>
                <span className="faq-icon">
                  <span className="material-symbols-outlined">
                    {openIndex === i ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}
                  </span>
                </span>
              </button>
              <div className="faq-answer">
                <p>{item.a}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default FaqSection;
